// Classify an inbound reply to the GDRock cold-outreach mailbox.
// Mirrors reply_watch.py: drop bounces + OOO/auto-replies, flag positives.
const item = $input.first().json;

const from = (item.from || item.fromAddress || item.sender || '').toString();
const m = from.match(/[\w.+-]+@[\w.-]+\.[A-Za-z]{2,}/);
const senderEmail = (m ? m[0] : from).toLowerCase().trim();
const subject = (item.subject || '').toString();
const body = (item.text || item.textPlain || item.textHtml || '').toString();
const blob = (from + ' ' + subject + ' ' + body).toLowerCase();

const BOUNCE = ['mailer-daemon','postmaster','mail delivery','delivery status','undeliverable','delivery has failed','returned mail','message could not be delivered'];
const AUTO = ['auto-reply','autoreply','automatic reply','automatische','out of office','out-of-office','vacation','away from','currently out','currently away','off-grid','off grid','on leave','annual leave','maternity','parental leave','will be back','back in the office','back on ','limited access to email','reduced availability','upcoming schedule','noreply','no-reply','do-not-reply'];
const POSITIVE = ['yes','send','audit','sure','interested','please','go ahead','sounds good','keen','ja','oui'];

const isBounce = BOUNCE.some(s => blob.includes(s));
const isAuto   = AUTO.some(s => blob.includes(s));

// Drop bounces and auto-replies — they are not human leads. Returning [] stops the branch.
if (isBounce || isAuto) { return []; }

const hay = (subject + ' ' + body).toLowerCase();
const esc = w => w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const isPositive = new RegExp('\\b(' + POSITIVE.map(esc).join('|') + ')\\b').test(hay);

const snippet = (body || subject).replace(/\s+/g, ' ').trim().slice(0, 400);
const dom = senderEmail.split('@')[1] || '';
const company = dom ? dom.replace(/\.[a-z.]+$/, '') : senderEmail;

// ── EDIT THIS once cal.com is live (also set GDROCK_CAL_LINK for the Python path) ──
const CAL_LINK = 'https://cal.eu/gdrock/15min';

const alertText =
  '🔥 REPLY — ' + (company || senderEmail) + ' (' + senderEmail + ')\n' +
  'Subject: ' + subject + '\n' +
  'Message: ' + snippet + '\n' +
  'Respond within 15 min.';

const positiveText =
  '✅ POSITIVE — ' + (company || senderEmail) + ' (' + senderEmail + ')\n' +
  'They sound interested. Send the audit + booking link:\n' +
  CAL_LINK + '\n\n“' + snippet + '”';

return [{ json: { senderEmail, company, dom, subject, snippet, isPositive, alertText, positiveText, replied_at: new Date().toISOString() } }];

// Only continue for positive replies (yes / send / interested ...).
if (!$input.first().json.isPositive) { return []; }
return $input.all();
